INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101187, 28, 'for', 'ea6f2988-62b9-5a2f-832e-de4b2a9ee8c6', 'The numbers ended the amateurism debate before the lawyers did. The NCAA signed tournament TV deals worth billions while the athletes generating the product got cost-of-attendance stipends. The House settlement approved in June 2025 sends about $2.8 billion in back damages to former athletes and lets schools share up to $20.5 million per year directly with players, according to [NCAA announcements](https://www.ncaa.org/). If a university can pay a football coach $10 million a year from revenue the players produce, calling those players ''student-athletes'' instead of employees is a legal fiction. Employees get minimum wage, workers'' comp, and a union voice. College athletes get concussions and a pat on the back. Classify them as employees and the fiction ends.', 11, '2026-09-24 10:48:11+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101188, 28, 'for', '7062708e-18b3-5d30-bc74-2c1d48b23543', 'I was a college soccer player, and my senior year I tore my ACL in a conference semifinal. The school covered the surgery, but the rehab schedule, the lost summer internship, and the chronic knee pain at 30 were mine to keep. Employees get workers'' compensation when they are hurt doing their job. College athletes get hurt doing exactly their job and then get told the scholarship was the compensation. The NLRB''s general counsel said in a [2021 memo](https://www.nlrb.gov/) that scholarship athletes at private schools meet the legal definition of employees. The Dartmouth men''s basketball team voted to unionize in March 2024. Employee status is not about turning campuses into pro franchises. It is about a 20-year-old with a spinal injury not begging for an MRI.', 12, '2026-09-24 12:28:30+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101189, 28, 'for', '2914ba68-d865-5196-ad0d-893256c22cc9', 'Graduate teaching assistants won employee status decades ago, and nobody claimed it destroyed the university. They teach classes, grade papers, and get paychecks, benefits, and unions. A starting quarterback works longer hours, generates more revenue, and faces greater physical risk, yet is told a scholarship is enough. Courts have already moved: the NLRB regional director ruled Dartmouth basketball players are employees, and the [House settlement](https://www.ncaa.org/) effectively conceded players deserve a share of revenue. Employee classification does not mean every swimmer gets rich. It means labor law applies: minimum wage floors, safety standards, and the right to bargain. We do not ask whether the chemistry department makes money before granting TAs workplace rights. Stop asking it about athletes.', 19, '2026-09-24 12:04:36+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101190, 28, 'against', 'e5cd8450-ec25-5d34-8abc-fbf7a62ce129', 'Only about two dozen athletic departments in Division I turn a profit. The other 300-plus subsidize sports with student fees and university funds. If football and basketball players become employees with salaries and benefits, the math is brutal: schools will cut the sports that lose money. That means swimming, wrestling, gymnastics, track, and most women''s sports outside basketball. Title IX requires equal opportunity, but equal employee payrolls across dozens of teams would bankrupt mid-major programs overnight. The [NCAA](https://www.ncaa.org/) reports more than 500,000 athletes compete across its divisions. Employee status might enrich a few thousand stars in revenue sports and eliminate opportunities for hundreds of thousands of others. That trade is not progress.', 26, '2026-09-24 10:22:59+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101191, 28, 'against', '8139a50e-240b-551e-85f5-ec8b818d23be', 'My daughter plays Division III softball. No TV money, no NIL deals, just a sport she loves and a degree she is earning. Classifying athletes as employees turns every roster spot into a labor decision: schools will carry fewer players, cut walk-ons, and treat the third-string catcher as a cost center. The classroom relationship matters too. Professors already navigate awkward dynamics with athletes; making them university employees with HR files deepens the divide between athlete-workers and regular students. NIL rights since 2021 already let stars earn real money, with some quarterbacks signing deals worth millions, as covered by the [Associated Press](https://apnews.com/). Let the market pay the marketable through NIL and revenue sharing. Do not reclassify the entire system and crush the 98 percent who just want to compete and graduate.', 7, '2026-09-24 12:48:13+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101192, 28, 'against', '63413976-38af-50d5-9354-2b535ac4e9d4', 'Employee status sounds simple until you administer it. Are athletes employees of the university, the conference, or the NCAA? Who pays unemployment insurance when a senior graduates? Do transfer portal moves trigger labor disputes? What happens to international athletes whose visas forbid employment? The Dartmouth vote applied to one Ivy League basketball team; scaling that ruling to 500,000 athletes across 1,100 schools with different state labor laws is a compliance nightmare. Workers'' comp alone would be staggering in football. And collective bargaining at public universities runs into state laws that vary wildly, some banning public-employee strikes entirely. The [House settlement''s](https://www.ncaa.org/) revenue-sharing model already delivers pay without detonating the legal framework. Employee classification promises fairness and delivers a decade of lawsuits.', 23, '2026-09-24 13:25:18+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101193, 29, 'for', '9bafda97-6949-58cd-abd2-1696b1e9c306', 'As a cardiac nurse, I dread the Monday after the spring clock change. A 2014 study presented to the American College of Cardiology found a 24 percent spike in heart attacks that day, and a 2020 study in Current Biology found fatal car crashes rise about 6 percent in the week after we spring forward. Our bodies run on circadian rhythm, not legislation, and losing an hour of sleep is a population-level stress test. The [American Academy of Sleep Medicine](https://aasm.org/) formally supports permanent standard time, noting morning light is what anchors healthy sleep. The Senate unanimously passed the Sunshine Protection Act in 2022 to lock the clock, but sleep scientists say permanent daylight time is the wrong half of the choice. Abolish the switching, keep standard time, and stop the twice-yearly health shock.', 7, '2026-09-24 11:57:08+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101194, 29, 'for', '83b1ec98-9ff0-5c5e-aa12-e20561952703', 'Every November and March, my household spends a week recovering from a government-mandated jet lag. My kids'' bedtimes slide, mornings become battles, and teachers report the same fog in every classroom. The original energy-saving argument collapsed years ago: a 2008 Department of Energy study found the extension of daylight time saved about half a percent of electricity, a rounding error. Meanwhile Arizona and Hawaii skip the whole ritual and function perfectly well, as [Reuters](https://www.reuters.com/) coverage of the debate regularly notes. Russia tried permanent daylight time in 2011 and abandoned it after public outcry over dark winter mornings, switching to permanent standard time in 2014. The experiment has been run. The switching helps almost nobody and disrupts everybody. End it.', 13, '2026-09-24 10:12:37+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101195, 29, 'for', '6a8c57ce-0e94-52e0-8aa7-3783561987a2', 'I manage a warehouse with overnight shifts, and the clock changes are a genuine operational hazard. Scheduling software glitches, timecards need manual fixes, and tired forklift drivers are a safety risk nobody should accept for tradition. Federal research on shift work documents that chronic sleep deprivation raises the risk of workplace injury, and the Bureau of Labor Statistics has tracked the growth of non-daytime schedules for years: [CDC/NIOSH](https://stacks.cdc.gov/view/cdc/164868/cdc_164868_DS1.pdf). We voluntarily add a fatigue spike twice a year. Farmers, the group the myth claims this is for, have opposed it for a century because cows do not read clocks. The EU voted back in 2019 to end seasonal clock changes and then never implemented it, which tells you everything about political inertia. One fixed time, year round, and businesses can plan around reality instead of a 100-year-old experiment.', 16, '2026-09-24 11:04:10+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101196, 29, 'against', '32d319a3-8952-564b-85ec-3c03f956e1d3', 'Permanent standard time means summer sunsets around 8 instead of 9, and anyone with kids in evening sports knows what that costs. Youth baseball, soccer practice, neighborhood bike rides, all of it runs on after-dinner daylight. The golf industry once estimated an extra month of daylight time was worth hundreds of millions in revenue, and the barbecue and recreation industries say the same. The Senate''s Sunshine Protection Act chose permanent daylight time for a reason: people vote with their evenings. [YouGov polling](https://yougov.com/en-us/articles/54237-the-times-they-are-a-changin-but-most-americans-would-rather-they-not) has shown Americans dislike the switching but split on which time to keep, with a tilt toward more evening light. Abolishing the change by locking in standard time trades dark winter mornings for dark summer evenings. That is not obviously a win.', 12, '2026-09-24 10:02:25+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101197, 29, 'against', '10625523-a431-5678-888f-8127f2e8c8eb', 'Daylight in the evening is a public safety tool. Study after study finds robbery and assault drop when the evening commute happens in daylight rather than darkness. Shifting an hour of light to the morning helps almost nobody: kids are in school and adults are at desks either way. But that same hour in the evening puts joggers, trick-or-treaters, and commuters in visible, safer conditions. Researchers analyzing crime data have estimated permanent daylight time could prevent tens of thousands of robberies a year. The sleep researchers pushing permanent standard time, like the [American Academy of Sleep Medicine](https://aasm.org/), are optimizing for one variable while ignoring how people actually live. If we abolish the switch, keep the daylight where it protects people: the evening.', 4, '2026-09-24 12:48:16+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101198, 29, 'against', 'bb708620-1c6d-50d3-b168-cdc7570a1c9f', 'We have tried to fix the clock before and made a mess. In 1974 the U.S. tried year-round daylight time during the energy crisis and parents revolted over children waiting for school buses in the dark; it was repealed within a year. Russia''s 2011 experiment with permanent daylight time ended the same way, with a switch to permanent standard time in 2014. Every option has a constituency that hates it, which is why the current compromise survives: we muddle through two transitions a year that most people adjust to within days. The [Associated Press](https://apnews.com/) has covered how the Sunshine Protection Act keeps stalling precisely because nobody agrees on the replacement. Abolishing the switch sounds decisive until you have to pick the time, and then the fight starts over. Sometimes the devil you know is the policy.', 15, '2026-09-24 11:24:19+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101199, 15, 'for', 'a50e13cf-78a7-5092-8a1a-a13fc4738307', 'Enforcement always chases the biggest names, which leaves the long tail of apps quietly selling your location. The FTC''s Outlogic order made headlines, but thousands of smaller SDKs and data brokers never see a regulator. Automatic audits flip the incentive: instead of betting you are too small to get caught, every company handling location data knows an independent review is coming. The [FTC''s own orders](https://www.ftc.gov/) already impose 20-year audit requirements on caught violators; making the trigger automatic just extends that protection to users who will never be named in a press release. Most people cannot tell which apps sell their movements. An automatic audit can.', 11, '2026-09-23 19:00:28+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101200, 15, 'against', '49778c11-6803-5c54-b317-c000fc8ab49a', 'There are not enough qualified, genuinely independent auditors to review every company that trips an automatic trigger. Demand would spike, prices would follow, and the cost lands on users through higher prices or on startups through another compliance bill they cannot afford. The biggest firms would simply buy up audit capacity, recreating the cozy auditor-client relationship the proposal claims to fix. Meanwhile the actual harm, data already sold to brokers, cannot be unaudited; you cannot unring that bell, as the deletion and ban remedies in the [Outlogic settlement](https://thehackernews.com/2024/01/ftc-bans-outlogic-x-mode-from-selling.html) implicitly admitted. Spend the money on banning the sale of precise location data outright. An audit industry is a jobs program, not a privacy fix.', 23, '2026-09-23 18:43:34+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101201, 16, 'for', '2336fb05-0e39-5cf2-8b0f-2437b4583c24', 'Voluntary principles have a jurisdiction problem: a company can simply route around them. When one country tightens AI or data rules, development shifts to wherever the rules are loosest, and users everywhere live with the consequences. That is regulatory arbitrage, and it is exactly what happened with data havens and tax havens. The [OECD AI Principles](https://www.oecd.org/) are explicitly non-binding, so compliance is a branding choice. Enforceable international rules set a floor nobody can undercut, the way aviation safety standards work through the ICAO. Without a floor, the most responsible companies face the highest costs, which punishes exactly the behavior we want. A binding minimum does not require a world government. It requires countries to agree that some harms should be illegal everywhere.', 8, '2026-09-24 01:46:40+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101202, 16, 'against', '839d2e94-4146-5ea3-9258-858df8438a08', 'A binding global rule gets written by committee, which means it gets written to the lowest common denominator. The result locks in weak standards and, worse, can preempt stronger national laws: once a global ceiling exists, industry lobbies to treat it as the final word. Voluntary frameworks let leaders go further, and history shows norms often harden into law after the best practices are proven. The [EU''s DSA](https://edaa.eu/digital-services-act/enforcement-and-penalties/) can levy 6 percent fines because it sits inside a real legal union with courts; a global equivalent has no such foundation. Better to let ambitious jurisdictions compete upward than to chain everyone to a compromise drafted to satisfy 190 governments.', 4, '2026-09-23 17:59:35+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101203, 17, 'for', '9778618a-eecd-5dfb-bda6-485db1214b50', 'Prime time is where the sponsorship money lives, and sponsorship money is what funds the pipeline everyone says women''s cricket needs. Broadcasters charge premium rates for evening slots, brands pay to be near big audiences, and that revenue flows back into production, marketing, and grassroots coverage. Keep milestones buried in afternoon slots and the commercial case stays weak forever: no audience numbers, no sponsor interest, no investment. The 2020 Women''s T20 World Cup final drew [86,174 fans at the MCG](https://www.icc-cricket.com/news/australia-lift-fifth-t20-world-cup-title), proof the demand exists when the stage is big enough. Equal prime-time promotion is not charity. It is the commercial flywheel that turns a milestone into a market.', 9, '2026-09-23 21:43:08+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101204, 17, 'against', '52a46b83-4565-5129-a637-fd419d63dca9', 'Prime-time slots are not sitting empty waiting for an editor''s conscience. They are sold years in advance inside broadcast rights packages worth billions, with contractual guarantees about placement and promotion. A mandate for equal prime-time promotion would have leagues and broadcasters litigating what equal means while rights holders sue over breached contracts. The [viewing growth](https://www.sportsbusinessjournal.com/Articles/2026/09/08/study-network-highlight-show-coverage-of-wom) in women''s sports is real, and broadcasters are already expanding coverage because audiences are growing, which is how markets should work. Let the next round of rights deals price in the rising demand. Forcing it by rule invites legal chaos for a problem that commercial momentum is already solving.', 11, '2026-09-23 14:33:54+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101205, 18, 'for', '8980bdc4-cf9c-5366-a25f-30c4e4ae5a24', 'Medals are wonderful, but participation pays the treasury back. Every inactive adult who takes up a funded community sport is less likely to develop the chronic conditions that devour health budgets: heart disease, diabetes, depression. Public health economists have repeatedly found that physical activity programs return several dollars in avoided healthcare costs for each dollar spent. Funding formulas that only reward podiums treat sport as entertainment; formulas that reward participation treat it as preventive medicine. The [UK Sport consultation](https://www.uksport.gov.uk/) showed the public already sees this connection, with a fifth of public respondents backing broader measures. A funding system that ignores health savings is leaving public money on the table.', 10, '2026-09-23 18:58:55+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101206, 18, 'against', '51ff2156-709e-5bbd-aeed-c5e0ae20bb4e', 'Participation already has its funding streams: school PE budgets, public health grants, community recreation departments, and lottery-funded grassroots programs. Routing elite sports money toward the same goal double counts what other budgets already buy, while starving the one thing only national funding can do, which is produce world-class athletes. Nobody asks the health department to fund Olympic training centers; the sports budget should not be asked to fund what the health department already covers. The existing [consultation data](https://www.uksport.gov.uk/) showed even sector stakeholders split on this, with most backing elite focus for elite money. Keep the streams separate and judge each on its own results instead of blurring every budget into everything.', 4, '2026-09-23 17:58:59+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101207, 19, 'for', '4a8f4a7e-c9c8-5980-91d6-bb07f645fc75', 'Every unequal bonus schedule is a future lawsuit with legal bills attached. Federations have spent years and millions litigating equal-pay claims that standardized bonuses would have prevented: one schedule, one formula, no discovery phase. The [U.S. Soccer deal](https://www.ussoccer.com/) through 2028 proved identical economic terms are workable, including pooled World Cup prize money. Standardization also ends the annual negotiation circus where each record triggers a fresh argument about what it was worth. Administrators know exactly what a record costs before it happens, sponsors know the story, and athletes know the deal. Paying lawyers to argue about fairness year after year is the most expensive bonus policy of all.', 19, '2026-09-23 15:40:25+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101208, 19, 'against', '06ce25a4-efd8-5581-88f7-c154d4c5c6b6', 'Standardization cuts both ways, and its supporters forget the sports where the women''s game generates more. In tennis, women''s finals have outdrawn men''s at some events; in several Olympic cycles, women''s teams have been the bigger draw for sponsors. A single standardized schedule would cap those bonuses at the men''s level or drag everyone to an average that shortchanges whoever performs better commercially. The [FIFA prize pools](https://pfa.net.au/the-pfa-post/pfa-post-womens-world-cup-prize-money-explained/) differ because the tournaments'' revenues differ, and pretending otherwise does not help women athletes. It constrains them. Let each program''s bonuses reflect its own economics, and let thriving women''s programs pay more than the men when they earn it.', 17, '2026-09-24 03:24:01+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101209, 20, 'for', '8980bdc4-cf9c-5366-a25f-30c4e4ae5a24', 'Skeptics say AI cannot be inspected, but the supply chain says otherwise. Frontier models require enormous compute, and advanced chips come from a tiny number of suppliers and fabs. That concentration makes verification technically feasible in a way treaties rarely enjoy: you can count data centers, meter power usage, and track chip shipments. The [UN advisory body''s](https://sdg.iisd.org/news/secretary-generals-advisory-body-makes-proposals-to-govern-a) recommendations already point toward shared scientific capacity and monitoring. Nuclear inspectors verify enrichment facilities they cannot fully see inside; AI inspectors could verify compute thresholds the same way. An international body with real authority would not need to read every model''s weights. It would need the power to audit the handful of facilities where frontier training is physically possible.', 24, '2026-09-23 17:15:25+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101210, 20, 'against', '51ff2156-709e-5bbd-aeed-c5e0ae20bb4e', 'A body with real authority over AI faces an impossible choice: be toothless or be captured. If inspections are voluntary, the countries racing hardest simply build outside the system, and the body becomes a club for the compliant. If inspections are mandatory, no great power will grant foreign inspectors access to its most strategic technology, so the authority exists only on paper. Either way, the institution ends up serving whoever funds and staffs it, likely the current tech leaders, who then write the thresholds to suit themselves. The [OECD principles](https://www.oecd.org/) stay non-binding precisely because binding commitments on this technology are not credible yet. Build shared safety science first. Authority without credible enforcement is theater, and theater is what gets people hurt.', 9, '2026-09-23 13:55:19+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
